export const TOP_50_AI = TOP_150_AI;
export const TOP_AI_COINS = TOP_150_AI;

export type RadarUniverseTab = "majors" | "memes" | "ai" | "custom";

export function getUniverseCoins(
  tab: RadarUniverseTab,
  customSymbols: string[] = []
): CuratedCoin[] {
  switch (tab) {
    case "majors":
      return MAJORS_UNIVERSE;
    case "memes":
      return TOP_150_MEMES;
    case "ai":
      return TOP_150_AI;
    case "custom":
      return customSymbols.map((sym) => {
        const upper = sym.toUpperCase().trim();
        const normalized = upper.endsWith("USDT") ? upper : `${upper}USDT`;
        const found =
          MAJORS_UNIVERSE.find((c) => c.symbol === normalized) ||
          TOP_150_MEMES.find((c) => c.symbol === normalized) ||
          TOP_150_AI.find((c) => c.symbol === normalized);
        return {
          symbol: normalized,
          contractSymbol: found?.contractSymbol ?? normalized.replace(/USDT$/, "_USDT"),
          name: found ? found.name : upper.replace(/USDT$/, ""),
          category: "majors",
          marketType: "futures",
        };
      });
    default:
      return MAJORS_UNIVERSE;
  }
}
